#ifndef CNET_SCTP_GMSSL_MAC_INTERNAL_H
#define CNET_SCTP_GMSSL_MAC_INTERNAL_H

#include "sctp_assoc_internal.h"

/* M2 security research: private, C11-only GmSSL cookie MAC adapter.
 * THIS HEADER MUST NOT BE EXPORTED INTO ANY INSTALLED SDK.
 * Key material must be generated by the owning application's CSPRNG, and the
 * owner must keep the provider alive until every association has drained.
 * Rotation with overlapping prior-epoch validity is not implemented.
 */
#define CNET_SCTP_GMSSL_KEY_BYTES 32u

typedef struct cnet_sctp_gmssl_mac {
  uint8_t key[CNET_SCTP_GMSSL_KEY_BYTES];
  unsigned int active;
} cnet_sctp_gmssl_mac;

/* The caller must zero-initialize the provider before first initialization.
 * Source key bytes are copied, never borrowed. Caller must wipe its own copy.
 */
int cnet_sctp_gmssl_mac_init(cnet_sctp_gmssl_mac *provider,
                            const uint8_t *key, size_t key_length);

/* Callback compatible with cnet_sctp_assoc_mac_fn when a MAC provider is
 * used directly as the callback context. 0 = success; -1 = fail closed.
 */
int cnet_sctp_gmssl_mac_sign(void *provider,
                            const uint8_t *message, size_t message_size,
                            uint8_t out[CNET_SCTP_ASSOC_MAC_BYTES]);

/* The owner must first stop and drain all associations using this key.
 * The provider is unusable after retirement, even if sign is invoked late.
 */
void cnet_sctp_gmssl_mac_retire(cnet_sctp_gmssl_mac *provider);

#endif
